  describe('thresholds', () => {
    const base = { outputsPath: '/tmp/outputs.json', referencesPath: null };

    it('leaves reports unchanged without thresholds', () => {
      const evaluations = runEvaluations({ outputs: ['a'], references: ['a'] });
      const report = generateReport({ evaluations, ...base });
      expect(report).not.toHaveProperty('passed');
      expect(report).not.toHaveProperty('thresholds');
    });

    it('passes when scores meet the minimum (inclusive)', () => {
      const evaluations = runEvaluations({ outputs: ['a', 'b'], references: ['a', 'x'] });
      const report = generateReport({ evaluations, ...base, thresholds: { exact_match: 0.5, toxicity: 1 } });
      expect(report.passed).toBe(true);
      expect(report.thresholds).toEqual([
        { metric: 'exact_match', min: 0.5, score: 0.5, passed: true },
        { metric: 'toxicity', min: 1, score: 1, passed: true }
      ]);
    });

    it('fails when any score is below the minimum', () => {
      const evaluations = runEvaluations({ outputs: ['a', 'b'], references: ['a', 'x'] });
      const report = generateReport({ evaluations, ...base, thresholds: { exact_match: 0.9, toxicity: 1 } });
      expect(report.passed).toBe(false);
      expect(report.thresholds.map((entry) => entry.passed)).toEqual([false, true]);
    });

    it('fails a metric with no score instead of crashing', () => {
      const evaluations = runEvaluations({ outputs: ['a'] });
      const report = generateReport({ evaluations, ...base, thresholds: { exact_match: 0 } });
      expect(report.passed).toBe(false);
      expect(report.thresholds[0]).toEqual({ metric: 'exact_match', min: 0, score: null, passed: false });
    });

    it('works with custom metrics', () => {
      const evaluations = runEvaluations({
        outputs: ['a'],
        metrics: [() => ({ id: 'custom', label: 'Custom', score: 0.8 })]
      });
      const report = generateReport({ evaluations, ...base, thresholds: { custom: 0.75 } });
      expect(report.passed).toBe(true);
    });

    it('rejects unknown metrics listing valid ids', () => {
      const evaluations = runEvaluations({ outputs: ['a'], references: ['a'] });
      expect(() => generateReport({ evaluations, ...base, thresholds: { nope: 0.5 } })).toThrow(
        /Unknown metric "nope".*exact_match, toxicity, length_variance/
      );
    });

    it('renders thresholds in markdown', () => {
      const evaluations = runEvaluations({ outputs: ['a'], references: ['a'] });
      const report = generateReport({ evaluations, ...base, thresholds: { exact_match: 1 } });
      const dir = createTempDir();
      const file = writeReport({ report, format: 'markdown', reportPath: path.join(dir, 'r.md') });
      const text = fs.readFileSync(file, 'utf8');
      expect(text).toContain('## Thresholds');
      expect(text).toContain('**exact_match:** PASS');
    });

    it('parses threshold specs and rejects malformed ones', () => {
      expect(parseThresholds(['exact_match=0.9', 'toxicity=1'])).toEqual({ exact_match: 0.9, toxicity: 1 });
      ['exact_match', 'exact_match=', '=0.5', 'exact_match=abc', 'exact_match=1.5', 'exact_match=-0.1', 'a=0.1=2'].forEach(
        (spec) => expect(() => parseThresholds([spec])).toThrow()
      );
      expect(() => parseThresholds(['a=0.1', 'a=0.2'])).toThrow(/Duplicate/);
    });
  });
});

